Lemma mmap_gates_core34 : forall flags,
  mmap_flags_core flags = 34%Z ->
  mmap_modeled_b (Z_to_bv 64 3) flags (Z_to_bv 64 0) = true
  /\ mmap_modeled_b (Z_to_bv 64 0) flags (Z_to_bv 64 0) = false
  /\ mmap_noaccess_b (Z_to_bv 64 0) flags (Z_to_bv 64 0) = true.
Proof. ltac2:(RplC.RP.run_k (rplG ()) 0 "S16;A1;o6;Y6;00;A1;o147;Y5;02;A2;k149;#0;A1;o147;Y1;1;A2;k12;k314;k315;A2;k251;A2;k10;#0;#2;#3;A2;k12;k316;k317;A2;k251;r1;#5;A2;k149;#0;o68;A1;k318;#7;A2;k10;#0;#7;A2;k251;#9;#3;A2;k251;#9;k319;A2;k251;#1;#5;A3;i23;i18;A2;k20;A2;k20;#10;#12;#8;o71;A3;i23;i18;A2;k20;A2;k20;#11;#12;#8;o30;A2;o17;i18;o30;Lflags;RA1;i5;#0;LHc;RA3;i23;i16;A1;k306;r1;#1;cdA6;k86;i16;#1;Lz;Ri16;A2;i7;A3;i23;i18;A2;k20;A2;k20;#4;#6;#8;o30;A2;i7;A3;i23;i18;A2;k20;A2;k20;#10;#6;#8;o71;A3;i23;i18;A2;k20;A2;k20;#11;#6;#8;o30;A4;o38;A3;i23;i18;A2;k20;A2;k20;#4;#12;#8;o30;A2;i7;#13;#14;#15;A4;o38;#13;#14;A2;o17;i18;o71;#15;A1;k306;r2;r1;A2;i7;A3;i23;i18;A3;k320;#2;r2;#7;o30;A2;i7;A3;i23;i18;A3;k320;#7;r2;#7;o71;A3;i23;i18;A3;k321;#7;r2;#7;o30;").
Qed.

Lemma mmap_gates_core50 : forall flags prot,
  mmap_flags_core flags = 50%Z ->
  mmap_modeled_b prot flags (Z_to_bv 64 0) = false
  /\ mmap_noaccess_b prot flags (Z_to_bv 64 0) = false
  /\ mmap_fixed_noaccess_b (Z_to_bv 64 0) flags (Z_to_bv 64 0) = true
  /\ mmap_fixed_noaccess_b (Z_to_bv 64 3) flags (Z_to_bv 64 0) = false
