Definition kind_none (k : mkind) : bool := ltac2:(RplC.RP.run_k (rplG ()) 1 "S0;Lk;Ri267;m267;RNLk;Ri267;i18;r1;6;o71;o71;o30;o30;o71;o71;").
Definition kind_lazy (k : mkind) : bool := ltac2:(RplC.RP.run_k (rplG ()) 1 "S0;Lk;Ri267;m267;RNLk;Ri267;i18;r1;6;o71;o30;o71;o30;o71;o71;").

Record grant_post (kd : mkind) (a n : word) (model model' : Model) : Prop := GP {
  gp_maps : vm_maps (m_vmmaps model') = (a, n) :: vm_maps (m_vmmaps model);
  gp_res : vm_reserved (m_vmmaps model') = vm_reserved (m_vmmaps model);
  gp_noacc : vm_noaccess (m_vmmaps model') = (if kind_none kd then (a, n) :: vm_noaccess (m_vmmaps model) else vm_noaccess (m_vmmaps model));
  gp_lazy : m_vm_lazy model' = (if kind_lazy kd then (a, n) :: m_vm_lazy model else m_vm_lazy model);
  gp_mat : m_vm_materialized model' = m_vm_materialized model;
  gp_limit : vm_limit (m_vmmaps model') = vm_limit (m_vmmaps model);
  gp_brk : vm_brk (m_vmmaps model') = vm_brk (m_vmmaps model);
  gp_sbrk : vm_start_brk (m_vmmaps model') = vm_start_brk (m_vmmaps model);
  gp_mbase : vm_mmap_base (m_vmmaps model') = vm_mmap_base (m_vmmaps model);
  gp_halted : m_halted model' = m_halted model;
  gp_fds : m_fds model' = m_fds model;
  gp_fs : m_fs model' = m_fs model;
  gp_tid : m_tid model' = m_tid model;
  gp_isp : vm_init_sp (m_vmmaps model') = vm_init_sp (m_vmmaps model);
  (* NEW FIELD, APPENDED so every existing positional projection keeps its meaning.
     [cs_ok] gained [co_vdso] at the revision (AsanPlanSoundK.v:330-337): the vdso/vvar
     pair the launch installed is part of the reserved ledger.  Carrying it across a grant
     needs the KERNEL BUILD framed, and this record framed fourteen projections without it.
     [vdso_top] needs no field of its own: it is [page_round_down_Z (mmap_top h)] and
     [mmap_top h] is [Z.min (bv_unsigned (vm_mmap_base h)) (page_round_down_Z (alloc_top h))]
     (State.v:3466, :3483 @ 75d69e00), so [gp_mbase] and [gp_isp] already determine it.
     No constructor of this record exists anywhere in the tree -- every occurrence of
     [grant_post] in proofs/ is a HYPOTHESIS -- so appending costs no producer a change
     today, and its eventual producer owes an equation that is true of every grant:
     a grant is a [with_vmmaps] rebuild and carries [m_kernel] through. *)
  gp_kernel : m_kernel model' = m_kernel model;
  (* LPS 727298f3: cs_ok's co_rdr reads the channel-reader flag, which a grant (a
     [with_vmmaps] rebuild) carries through; appended as gp_kernel was. *)
  gp_rdr : m_channel_reader model' = m_channel_reader model }.

Definition grant_mem (kd : mkind) (a n : word) (FULL FULL' : word -> option byte) : Prop := ltac2:(RplC.RP.run_k (rplG ()) 5 "S11;A1;o6;Y6;00;A1;i5;#0;Y3;0;A1;o6;#2;A1;i5;#3;A1;i204;#4;P~R#1;#5;A2;k10;#0;r1;A2;k10;#0;r5;A2;k12;#8;A2;k10;#0;r4;A1;r3;r2;Lkd;Ri267;La;R#1;Ln;R#1;LFULL;R#6;LFULL';R#6;A2;i7;Px;R#1;P~RA2;i93;A2;k35;#7;#8;A2;k8;#9;#7;A3;i23;#5;#10;A1;r4;r2;Px;R#1;P~RA2;i7;A2;k8;#8;#7;A2;k35;#7;#9;A3;i23;#5;#10;m18;RNL~Ri18;#5;A1;k660;r7;2;A1;o63;#4;A2;o205;#4;A2;k149;#3;o68;").

(* The ELIMINATION dual of [RefNodes.region_free_intro], which this tree had only in the
   introduction direction.  Needed because [cs_ok] gained [co_mres] at the revision (see the
   bullet at the end of [grant_cs1_ok]) and the new entry's half of it comes FROM a
   [region_free], not from another [co_mres].  Proved by induction, in the same shape as
   region_free_intro's, so the head test is the left operand of the [&&]. *)
Lemma region_free_disj : forall l (lo n : word) b s,
  region_free l lo n = true -> In (b, s) l ->
  bv_unsigned lo + bv_unsigned n <= bv_unsigned b \/ bv_unsigned b + bv_unsigned s <= bv_unsigned lo.
Proof.
  induction l as [|[b0 s0] l IH]; intros lo n b s H Hin; [contradiction|].
  cbn [region_free] in H. apply andb_prop in H as [Hhead Hrec].
  destruct Hin as [E|Hin].
  - injection E as <- <-. apply negb_true_iff in Hhead. unfold iv_overlap in Hhead.
    apply andb_false_iff in Hhead as [Hh|Hh]; apply Z.ltb_ge in Hh; [right|left]; lia.
  - exact (IH lo n b s Hrec Hin).
Qed.

